<?php
session_start();
require_once('check-login.php');
require_once('website-content-utils.php');
if(!isset($_SESSION['ACCESSLEVEL']) || $_SESSION['ACCESSLEVEL'] !== 'administrator'){ http_response_code(403); exit('Only system administrators can manage the public website.'); }
if(empty($_SESSION['website_editor_csrf'])){ $_SESSION['website_editor_csrf'] = bin2hex(random_bytes(32)); }
$message = ''; $messageClass = 'success'; $content = website_content_all($con); $previousContent = $content;
if($_SERVER['REQUEST_METHOD'] === 'POST'){
    if(!hash_equals($_SESSION['website_editor_csrf'], isset($_POST['csrf']) ? $_POST['csrf'] : '')){ $message = 'Your form expired. Please try again.'; $messageClass = 'error'; }
    else {
        $keys = array('report_eyebrow','report_title','report_title_emphasis','report_description','report_button_label','phone','email','address','facebook_url','tiktok_url','whatsapp_url');
        foreach($keys as $key){ $content[$key] = trim(isset($_POST[$key]) ? (string)$_POST[$key] : ''); }
        if(!filter_var($content['email'], FILTER_VALIDATE_EMAIL)){ $message = 'Enter a valid public email address.'; $messageClass = 'error'; }
        elseif(!filter_var($content['facebook_url'], FILTER_VALIDATE_URL) || !filter_var($content['tiktok_url'], FILTER_VALIDATE_URL) || !filter_var($content['whatsapp_url'], FILTER_VALIDATE_URL)){ $message = 'Enter complete links beginning with https:// for the social and WhatsApp links.'; $messageClass = 'error'; }
        else {
            if(isset($_FILES['report_image']) && $_FILES['report_image']['error'] !== UPLOAD_ERR_NO_FILE){
                $file = $_FILES['report_image']; $allowed = array('image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'); $mime = ($file['error'] === UPLOAD_ERR_OK && function_exists('mime_content_type')) ? mime_content_type($file['tmp_name']) : '';
                if($file['error'] !== UPLOAD_ERR_OK || $file['size'] > 5242880 || !isset($allowed[$mime]) || @getimagesize($file['tmp_name']) === false){ $message = 'The guide image must be a JPG, PNG, or WebP image no larger than 5 MB.'; $messageClass = 'error'; }
                else { $folder = __DIR__.DIRECTORY_SEPARATOR.'uploads'.DIRECTORY_SEPARATOR.'website'; if(!is_dir($folder) && !mkdir($folder,0755,true)){ $message='The website image folder could not be created.'; $messageClass='error'; } else { $filename='report-guide-'.date('Ymd-His').'-'.bin2hex(random_bytes(4)).'.'.$allowed[$mime]; if(move_uploaded_file($file['tmp_name'],$folder.DIRECTORY_SEPARATOR.$filename)){ $content['report_image']='uploads/website/'.$filename; } else { $message='The guide image could not be uploaded.'; $messageClass='error'; } } }
            }
            if($message === '' && website_content_save($con,$content,$_SESSION['USERID'])){
                $noticeKeys = array('report_eyebrow','report_title','report_title_emphasis','report_description','report_button_label','report_image');
                $noticeChanged = false;
                foreach($noticeKeys as $noticeKey){ if((string)$previousContent[$noticeKey] !== (string)$content[$noticeKey]){ $noticeChanged = true; break; } }
                if($noticeChanged){
                    website_announcements_ensure_table($con);
                    $archiveTitle = trim($previousContent['report_title'].' '.$previousContent['report_title_emphasis']);
                    $archiveText = trim($previousContent['report_description']);
                    if($archiveTitle !== '' && $archiveText !== ''){
                        $archiveTitle = substr($archiveTitle, 0, 180);
                        $archive = mysqli_prepare($con, 'INSERT INTO tblwebsiteannouncements (title, announcement_text, published_by) VALUES (?, ?, ?)');
                        if($archive){ $archiveUser = $_SESSION['USERID']; mysqli_stmt_bind_param($archive, 'sss', $archiveTitle, $archiveText, $archiveUser); mysqli_stmt_execute($archive); mysqli_stmt_close($archive); }
                    }
                }
                $message='Website changes published successfully.';
            }
            elseif($message === ''){ $message='The changes could not be saved. Please try again.'; $messageClass='error'; }
        }
    }
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Manage Website | AYISEC</title><link rel="stylesheet" href="css/font-awesome-4.7.0/css/font-awesome.min.css"><style>body{margin:0;background:#f3f6f8;color:#15283b;font:16px/1.5 Arial,sans-serif}.wrap{max-width:980px;margin:38px auto;padding:0 20px}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}.top h1{margin:0;font-size:30px}.top p{margin:3px 0 0;color:#64748b}.back,.preview{display:inline-block;padding:10px 15px;border-radius:7px;text-decoration:none;font-weight:bold}.back{color:#183650;background:#fff;border:1px solid #d7e0e8}.preview{background:#ca8a04;color:white}.notice{padding:13px 16px;margin:0 0 20px;border-radius:7px}.success{background:#dcfce7;color:#166534}.error{background:#fee2e2;color:#991b1b}.card{background:#fff;border:1px solid #dce5eb;border-radius:10px;padding:26px;margin-bottom:20px;box-shadow:0 4px 14px rgba(15,39,66,.05)}h2{font-size:21px;margin:0 0 6px}h2+p{margin-top:0;color:#64748b}label{display:block;font-weight:bold;margin:18px 0 6px}input,textarea{box-sizing:border-box;width:100%;border:1px solid #becbd5;border-radius:6px;padding:10px;font:inherit}textarea{min-height:86px;resize:vertical}.hint{font-size:13px;color:#64748b;margin:5px 0 0}.image-preview{max-width:220px;max-height:300px;border-radius:7px;border:1px solid #dce5eb;margin-top:10px}.actions{position:sticky;bottom:0;background:rgba(243,246,248,.95);padding:16px 0;text-align:right}button{border:0;border-radius:7px;padding:13px 20px;background:#0f4c75;color:white;font-weight:bold;font-size:16px;cursor:pointer}@media(max-width:600px){.top{align-items:flex-start;flex-direction:column}.wrap{margin-top:22px}}</style></head><body><main class="wrap"><div class="top"><div><h1>Manage Website</h1><p>Change public website content safely. The design and layout stay protected.</p></div><div><a class="back" href="admin.php">Admin home</a> <a class="preview" href="website.php" target="_blank">Preview website</a></div></div><?php if($message !== ''){ ?><div class="notice <?php echo website_content_escape($messageClass); ?>"><?php echo website_content_escape($message); ?></div><?php } ?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?php echo website_content_escape($_SESSION['website_editor_csrf']); ?>"><section class="card"><h2>Student report guide</h2><p>This is the notice displayed near the top of the school website.</p><label>Small heading</label><input name="report_eyebrow" maxlength="80" value="<?php echo website_content_escape($content['report_eyebrow']); ?>"><label>Main heading</label><input name="report_title" maxlength="100" value="<?php echo website_content_escape($content['report_title']); ?>"><label>Gold heading text</label><input name="report_title_emphasis" maxlength="100" value="<?php echo website_content_escape($content['report_title_emphasis']); ?>"><label>Description</label><textarea name="report_description" maxlength="500"><?php echo website_content_escape($content['report_description']); ?></textarea><label>Button label</label><input name="report_button_label" maxlength="60" value="<?php echo website_content_escape($content['report_button_label']); ?>"><label>Replace guide poster <small>(optional)</small></label><input type="file" name="report_image" accept="image/jpeg,image/png,image/webp"><p class="hint">JPG, PNG, or WebP; maximum 5 MB. The existing poster remains if you do not choose a file.</p><img class="image-preview" src="<?php echo website_content_escape($content['report_image']); ?>" alt="Current report guide poster"></section><section class="card"><h2>Public contact details</h2><p>Use a vertical bar <code>|</code> in the address to start a new line.</p><label>Phone number</label><input name="phone" maxlength="80" value="<?php echo website_content_escape($content['phone']); ?>"><label>Public email</label><input type="email" name="email" maxlength="160" value="<?php echo website_content_escape($content['email']); ?>"><label>Address</label><textarea name="address" maxlength="400"><?php echo website_content_escape($content['address']); ?></textarea></section><section class="card"><h2>Social and help links</h2><p>Paste the complete link for each service.</p><label>Facebook link</label><input type="url" name="facebook_url" value="<?php echo website_content_escape($content['facebook_url']); ?>"><label>TikTok link</label><input type="url" name="tiktok_url" value="<?php echo website_content_escape($content['tiktok_url']); ?>"><label>WhatsApp help link</label><input type="url" name="whatsapp_url" value="<?php echo website_content_escape($content['whatsapp_url']); ?>"></section><div class="actions"><button type="submit"><i class="fa fa-save"></i> Publish website changes</button></div></form></main></body></html>
